// NEW FILE: WorldExplorer/JetBlackEngineLib/Data/Executable/BgdaExecutable.ThreePlayer.cs
//
// Three-player co-op for SLES_506.72 (PAL): Adrianna the Elven Sorceress joins as
// player 3 through a "Three Player" entry in the main menu. One- and two-player
// games run the stock code.
//
// The patch is the exact difference between the stock executable and the tested
// ADRIANNA22 build (see BgdaExecutablePatches.cs, generated by
// make_worldexplorer_patch.py from the three-player tools). Turning it on checks that every byte it
// replaces is still the stock byte, writes the patched bytes and appends the
// staged code (the file grows from 2,274,512 to 5,235,712 bytes). Turning it off
// checks the patch is intact and writes the stock bytes back, so a stock file
// round-trips exactly. Edits made by the other tabs (XP, stats, feats, monster HP,
// difficulty scaling) are in places the patch never touches and survive both ways.
// Items added after the game's own (Items tab) live in the room the patch frees by moving
// the HUD's data, so three players can't be turned off while there are any.
//
// OLDER BUILDS: an executable that holds an earlier tested three-player build
// (ADRIANNA21 or ADRIANNA19, which this tab used to write, or ADRIANNA20) is
// recognised as Outdated. Its settings can be read and edited as usual, and it is
// updated to ADRIANNA22 in place (only the bytes that differ are rewritten; the
// settings below are the same bytes in all four builds and are kept).
//
// SETTINGS (only while three players are on; all apply to three-player games only)
//   BAL3 balance table  file 0x4FB000: monster HP, damage die, XP value, boss HP,
//                       gold per drop, item chance, gold chance, Orb of Undeath divisor
//   map markers         file 0x4FC180: one GS RGBA colour per player
//   small map           file 0x4FC108 (x, y) / 0x4FC120 (width, height)
// ═══════════════════════════════════════════════════════════════════════════════
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Security.Cryptography;
using System.Text;

namespace JetBlackEngineLib.Data.Executable;

public enum ThreePlayerState
{
    /// <summary>The stock executable: the patch can be turned on.</summary>
    Off,
    /// <summary>The three-player patch is present and intact: settings can be edited.</summary>
    On,
    /// <summary>
    /// An older tested three-player build (ADRIANNA21 / 20 / 19): settings can be edited and
    /// <see cref="BgdaExecutable.UpgradeThreePlayers"/> brings it to the current build.
    /// </summary>
    Outdated,
    /// <summary>Neither: another build or other changes where the patch lives.</summary>
    Unrecognized
}

/// <summary>An 8-bit RGB colour (automap marker).</summary>
public readonly record struct Rgb(int R, int G, int B);

/// <summary>Three-player settings stored in the patched executable.</summary>
public sealed class ThreePlayerSettings
{
    // ---- balance (BAL3); two players use 1.7 / 1.4 / 2 / 1.7 / 2 / 2 / 1.5 / 2 ----
    public float MonsterHp { get; set; }
    public float MonsterDamage { get; set; }
    public float XpValue { get; set; }
    public float BossHp { get; set; }
    public float GoldPerDrop { get; set; }
    public float ItemChance { get; set; }
    public float GoldChance { get; set; }
    /// <summary>Orb of Undeath: damage is divided by this (two players: 2).</summary>
    public int OrbDivisor { get; set; }

    /// <summary>Automap marker colour of players 1, 2 and 3.</summary>
    public Rgb[] Markers { get; set; } = new Rgb[3];

    // ---- small automap with three players (offset from the screen centre; +y is down) ----
    public float SmallMapX { get; set; }
    public float SmallMapY { get; set; }
    public float SmallMapWidth { get; set; }
    public float SmallMapHeight { get; set; }
}

public partial class BgdaExecutable
{
    public const float MinThreePlayerFactor = 0.01f;
    public const float MaxThreePlayerFactor = 100f;
    public const int MinOrbDivisor = 1, MaxOrbDivisor = 10;
    public const float MaxSmallMapOffset = 320f, MinSmallMapSize = 1f, MaxSmallMapSize = 640f;

    /// <summary>File length of the stock executable and of the three-player one.</summary>
    public const int StockFileLength = ThreePlayerPatch.StockLength;
    public const int ThreePlayerFileLength = ThreePlayerPatch.PatchedLength;

    /// <summary>Numbers in messages always use '.', matching what the editor accepts.</summary>
    private static string Inv(float v) => v.ToString(CultureInfo.InvariantCulture);

    private const uint MarkerAlpha = 0x80000000u;   // GS RGBA: alpha 0x80 = opaque

    // ---- patch data (decoded once, verified against its SHA-256) ----

    private sealed record PatchRun(int Offset, byte[] Stock, byte[] Patched);
    private sealed record TailRun(int Offset, byte[] Bytes);
    /// <summary>Where an older build differs from the current one: its bytes and the current bytes.</summary>
    private sealed record DeltaRun(int Offset, byte[] Old, byte[] New);
    private sealed record OlderBuild(string Name, DeltaRun[] Delta, Dictionary<int, byte> OldBytes);

    private static readonly Lazy<(PatchRun[] Runs, TailRun[] Tail, OlderBuild[] Older)> Patch = new(LoadPatch);

    /// <summary>The name of the build the patch writes (ADRIANNA22).</summary>
    public static string ThreePlayerBuildName => ThreePlayerPatch.CurrentName;

    /// <summary>The older three-player builds that are recognised and can be updated.</summary>
    public static IReadOnlyList<string> OlderThreePlayerBuilds =>
        Array.ConvertAll(Patch.Value.Older, o => o.Name);

    private static (PatchRun[] Runs, TailRun[] Tail, OlderBuild[] Older) LoadPatch()
    {
        var blob = Convert.FromBase64String(ThreePlayerPatch.BlobBase64);
        var hash = Convert.ToHexString(SHA256.HashData(blob)).ToLowerInvariant();
        if (hash != ThreePlayerPatch.BlobSha256)
            throw new InvalidDataException("The built-in three-player patch data is damaged.");

        var pos = 0;
        int U32()
        {
            var v = BitConverter.ToInt32(blob, pos);
            pos += 4;
            return v;
        }
        byte[] Bytes(int n)
        {
            var b = new byte[n];
            Array.Copy(blob, pos, b, 0, n);
            pos += n;
            return b;
        }

        if (Encoding.ASCII.GetString(blob, 0, 4) != "3PL2")
            throw new InvalidDataException("Unknown three-player patch format.");
        pos = 4;
        if (U32() != ThreePlayerPatch.StockLength || U32() != ThreePlayerPatch.PatchedLength)
            throw new InvalidDataException("Three-player patch lengths do not match.");

        var runs = new PatchRun[U32()];
        for (var i = 0; i < runs.Length; i++)
        {
            var off = U32();
            var len = U32();
            runs[i] = new PatchRun(off, Bytes(len), Bytes(len));
        }

        var tail = new TailRun[U32()];
        for (var i = 0; i < tail.Length; i++)
        {
            var off = U32();
            var len = U32();
            tail[i] = new TailRun(off, Bytes(len));
        }

        var older = new OlderBuild[U32()];
        for (var i = 0; i < older.Length; i++)
        {
            var name = Encoding.ASCII.GetString(Bytes(U32()));
            var delta = new DeltaRun[U32()];
            var oldBytes = new Dictionary<int, byte>();
            for (var k = 0; k < delta.Length; k++)
            {
                var off = U32();
                var len = U32();
                delta[k] = new DeltaRun(off, Bytes(len), Bytes(len));
                for (var j = 0; j < len; j++) oldBytes[off + j] = delta[k].Old[j];
            }

            older[i] = new OlderBuild(name, delta, oldBytes);
        }

        if (pos != blob.Length)
            throw new InvalidDataException("Three-player patch data has trailing bytes.");
        return (runs, tail, older);
    }

    // ---- state ----

    /// <summary>
    /// Off = stock, On = the current three-player patch is intact, Outdated = an older
    /// tested three-player build (updated on <see cref="UpgradeThreePlayers"/>), Unrecognized =
    /// anything else (an untested build, or other changes where the patch lives).
    /// <paramref name="detail"/> explains the verdict in a sentence.
    /// </summary>
    public ThreePlayerState GetThreePlayerState(out string detail) => GetThreePlayerState(out detail, out _);

    /// <summary>As <see cref="GetThreePlayerState(out string)"/>, also naming the build found
    /// (ADRIANNA22, ADRIANNA21, ADRIANNA20, ADRIANNA19), or null when there is none.</summary>
    public ThreePlayerState GetThreePlayerState(out string detail, out string? build)
    {
        var (runs, _, older) = Patch.Value;
        build = null;

        if (_data.Length == ThreePlayerPatch.StockLength)
        {
            var bad = FirstMismatch(runs, stock: true);
            if (bad < 0)
            {
                detail = "Stock executable: three players can be turned on.";
                return ThreePlayerState.Off;
            }

            detail = $"The executable has the stock length, but {CountMismatches(runs, true)} of " +
                     $"{runs.Length} places the three-player patch changes are already different " +
                     $"(first at file offset 0x{bad:X6}). It may hold another patch, so the switch is off-limits.";
            return ThreePlayerState.Unrecognized;
        }

        if (_data.Length == ThreePlayerPatch.PatchedLength)
        {
            var current = FirstBuildMismatch(null);
            if (current < 0 && HasBal3Header())
            {
                build = ThreePlayerPatch.CurrentName;
                detail = $"Three players are on (the tested {ThreePlayerPatch.CurrentName} patch).";
                return ThreePlayerState.On;
            }

            foreach (var o in older)
            {
                if (FirstBuildMismatch(o) >= 0 || !HasBal3Header()) continue;
                build = o.Name;
                detail = $"Three players are on with the older {o.Name} build. Saving updates it to " +
                         $"{ThreePlayerPatch.CurrentName} ({WhatTheUpdateAdds(o.Name)}); the three-player " +
                         "settings are kept.";
                return ThreePlayerState.Outdated;
            }

            // report the build it is closest to
            var (closest, count, first) = (ThreePlayerPatch.CurrentName, CountBuildMismatches(null), current);
            foreach (var o in older)
            {
                var c = CountBuildMismatches(o);
                if (c < count) (closest, count, first) = (o.Name, c, FirstBuildMismatch(o));
            }

            var names = string.Join(" / ", Array.ConvertAll(older, o => o.Name));
            detail = "The executable has the three-player length but is not a tested three-player build " +
                     $"({ThreePlayerPatch.CurrentName}, or {names} which can be updated): it is closest to {closest}, " +
                     $"but {count:N0} byte{(count == 1 ? " differs" : "s differ")} (first at file offset 0x{first:X6}). " +
                     "Open the stock SLES_506.72 or one of those builds.";
            return ThreePlayerState.Unrecognized;
        }

        detail = $"The executable is {_data.Length:N0} bytes; the stock one is " +
                 $"{ThreePlayerPatch.StockLength:N0} and the three-player one " +
                 $"{ThreePlayerPatch.PatchedLength:N0}, so the switch is off-limits.";
        return ThreePlayerState.Unrecognized;
    }

    public ThreePlayerState GetThreePlayerState() => GetThreePlayerState(out _, out _);

    private static string WhatTheUpdateAdds(string olderName) => olderName switch
    {
        "ADRIANNA21" => "its in-game memory counters then keep a record for each level, with the level's name",
        "ADRIANNA20" => "adds the in-game memory counters, with a record for each level",
        _ => "adds the graphics packet-buffer guard that stops the burnfrst cheat-menu freeze, and the in-game memory counters"
    };

    /// <summary>
    /// First file offset where the executable is not the given build (null = the current
    /// build), or -1. Checks every byte the current patch writes (runs inside the stock file
    /// and the non-zero appended data, settings excepted) and every byte where the older
    /// build differs from the current one.
    /// </summary>
    private int FirstBuildMismatch(OlderBuild? build)
    {
        var (runs, tail, _) = Patch.Value;
        byte Expected(int off, byte current) =>
            build != null && build.OldBytes.TryGetValue(off, out var b) ? b : current;

        foreach (var r in runs)
        {
            for (var i = 0; i < r.Patched.Length; i++)
            {
                var off = r.Offset + i;
                if (_data[off] != Expected(off, r.Patched[i])) return off;
            }
        }

        foreach (var t in tail)
        {
            for (var i = 0; i < t.Bytes.Length; i++)
            {
                var off = t.Offset + i;
                if (IsEditable(off)) continue;
                if (_data[off] != Expected(off, t.Bytes[i])) return off;
            }
        }

        if (build == null) return -1;
        foreach (var d in build.Delta)
        {
            for (var i = 0; i < d.Old.Length; i++)
            {
                var off = d.Offset + i;
                if (IsEditable(off)) continue;
                if (_data[off] != d.Old[i]) return off;
            }
        }

        return -1;
    }

    /// <summary>How many of the bytes <see cref="FirstBuildMismatch"/> checks differ.</summary>
    private int CountBuildMismatches(OlderBuild? build)
    {
        var (runs, tail, _) = Patch.Value;
        byte Expected(int off, byte current) =>
            build != null && build.OldBytes.TryGetValue(off, out var b) ? b : current;
        var n = 0;
        foreach (var r in runs)
        {
            for (var i = 0; i < r.Patched.Length; i++)
            {
                if (_data[r.Offset + i] != Expected(r.Offset + i, r.Patched[i])) n++;
            }
        }

        foreach (var t in tail)
        {
            for (var i = 0; i < t.Bytes.Length; i++)
            {
                var off = t.Offset + i;
                if (!IsEditable(off) && _data[off] != Expected(off, t.Bytes[i])) n++;
            }
        }

        if (build == null) return n;
        var counted = new HashSet<int>();
        foreach (var r in runs) for (var i = 0; i < r.Patched.Length; i++) counted.Add(r.Offset + i);
        foreach (var t in tail) for (var i = 0; i < t.Bytes.Length; i++) counted.Add(t.Offset + i);
        foreach (var d in build.Delta)
        {
            for (var i = 0; i < d.Old.Length; i++)
            {
                var off = d.Offset + i;
                if (!counted.Contains(off) && !IsEditable(off) && _data[off] != d.Old[i]) n++;
            }
        }

        return n;
    }

    private int FirstMismatch(PatchRun[] runs, bool stock)
    {
        foreach (var r in runs)
        {
            var want = stock ? r.Stock : r.Patched;
            for (var i = 0; i < want.Length; i++)
            {
                if (_data[r.Offset + i] != want[i]) return r.Offset + i;
            }
        }

        return -1;
    }

    private int CountMismatches(PatchRun[] runs, bool stock)
    {
        var n = 0;
        foreach (var r in runs)
        {
            var want = stock ? r.Stock : r.Patched;
            for (var i = 0; i < want.Length; i++)
            {
                if (_data[r.Offset + i] != want[i]) { n++; break; }
            }
        }

        return n;
    }

    private static bool IsEditable(int offset)
    {
        foreach (var (o, n) in ThreePlayerPatch.EditableRanges)
        {
            if (offset >= o && offset < o + n) return true;
        }

        return false;
    }

    private bool HasBal3Header() =>
        _data[ThreePlayerPatch.Bal3Offset] == (byte)'B' &&
        _data[ThreePlayerPatch.Bal3Offset + 1] == (byte)'A' &&
        _data[ThreePlayerPatch.Bal3Offset + 2] == (byte)'L' &&
        _data[ThreePlayerPatch.Bal3Offset + 3] == (byte)'3' &&
        BitConverter.ToInt32(_data, ThreePlayerPatch.Bal3Offset + 4) == 1;

    // ---- on / off ----

    /// <summary>
    /// Applies the three-player patch to a stock executable (state must be Off).
    /// Nothing is changed if the check fails.
    /// </summary>
    public void EnableThreePlayers()
    {
        if (GetThreePlayerState(out var detail) != ThreePlayerState.Off)
            throw new InvalidOperationException("Three players cannot be turned on: " + detail);

        var (runs, tail, _) = Patch.Value;
        var data = new byte[ThreePlayerPatch.PatchedLength];
        Array.Copy(_data, data, _data.Length);
        foreach (var r in runs) Array.Copy(r.Patched, 0, data, r.Offset, r.Patched.Length);
        foreach (var t in tail) Array.Copy(t.Bytes, 0, data, t.Offset, t.Bytes.Length);
        _data = data;
    }

    /// <summary>
    /// Brings an older tested three-player build (state Outdated) to the current build:
    /// only the bytes where they differ are rewritten, so the settings and every other
    /// tab's edits are kept. Nothing is changed if the check fails.
    /// </summary>
    public void UpgradeThreePlayers()
    {
        if (GetThreePlayerState(out var detail, out var build) != ThreePlayerState.Outdated)
            throw new InvalidOperationException("The three-player patch cannot be updated: " + detail);

        var o = Array.Find(Patch.Value.Older, x => x.Name == build)!;
        foreach (var d in o.Delta)
        {
            for (var i = 0; i < d.New.Length; i++)
            {
                if (!IsEditable(d.Offset + i)) _data[d.Offset + i] = d.New[i];
            }
        }
    }

    /// <summary>
    /// Removes the three-player patch (state must be On or Outdated): the stock bytes are
    /// written back and the file returns to its stock length. Three-player settings are lost.
    /// Refused while items are added after the game's own: they use the room the patch frees.
    /// </summary>
    public void DisableThreePlayers()
    {
        var state = GetThreePlayerState(out var detail);
        if (state is not (ThreePlayerState.On or ThreePlayerState.Outdated))
            throw new InvalidOperationException("Three players cannot be turned off: " + detail);
        if (AddedItemCount is var added and > 0)
        {
            throw new InvalidOperationException(
                $"Three players cannot be turned off while the item table has {added} added item{(added == 1 ? "" : "s")}: " +
                "they are kept where the stock game keeps the HUD's data. Remove them on the Items tab first.");
        }

        if (state == ThreePlayerState.Outdated) UpgradeThreePlayers();

        var (runs, _, _) = Patch.Value;
        var data = new byte[ThreePlayerPatch.StockLength];
        Array.Copy(_data, data, data.Length);
        foreach (var r in runs) Array.Copy(r.Stock, 0, data, r.Offset, r.Stock.Length);
        _data = data;
    }

    // ---- settings ----

    /// <summary>The settings as the patch ships them (the ADRIANNA22 values, the same in every tested build).</summary>
    public static ThreePlayerSettings DefaultThreePlayerSettings()
    {
        var image = new Dictionary<int, byte>();
        foreach (var t in Patch.Value.Tail)
        {
            for (var i = 0; i < t.Bytes.Length; i++) image[t.Offset + i] = t.Bytes[i];
        }

        byte At(int off) => image.TryGetValue(off, out var b) ? b : (byte)0;
        byte[] Read(int off, int n)
        {
            var b = new byte[n];
            for (var i = 0; i < n; i++) b[i] = At(off + i);
            return b;
        }

        return ReadSettings(Read);
    }

    /// <summary>Reads the three-player settings (state must be On or Outdated).</summary>
    public ThreePlayerSettings GetThreePlayerSettings()
    {
        RequireOn();
        return ReadSettings((off, n) =>
        {
            var b = new byte[n];
            Array.Copy(_data, off, b, 0, n);
            return b;
        });
    }

    private static ThreePlayerSettings ReadSettings(Func<int, int, byte[]> read)
    {
        var bal = read(ThreePlayerPatch.Bal3Offset, 0x28);
        float F(byte[] b, int at) => BitConverter.ToSingle(b, at);

        var markers = read(ThreePlayerPatch.MarkerOffset, 12);
        var pos = read(ThreePlayerPatch.SmallMapPosition, 8);
        var size = read(ThreePlayerPatch.SmallMapSize, 8);

        var s = new ThreePlayerSettings
        {
            MonsterHp      = F(bal, 0x08),
            MonsterDamage  = F(bal, 0x0C),
            XpValue        = F(bal, 0x10),
            BossHp         = F(bal, 0x14),
            GoldPerDrop    = F(bal, 0x18),
            ItemChance     = F(bal, 0x1C),
            GoldChance     = F(bal, 0x20),
            OrbDivisor     = BitConverter.ToInt32(bal, 0x24),
            SmallMapX      = F(pos, 0),
            SmallMapY      = F(pos, 4),
            SmallMapWidth  = F(size, 0),
            SmallMapHeight = F(size, 4)
        };
        for (var p = 0; p < 3; p++)
        {
            var w = BitConverter.ToUInt32(markers, p * 4);
            s.Markers[p] = new Rgb((int)(w & 0xFF), (int)((w >> 8) & 0xFF), (int)((w >> 16) & 0xFF));
        }

        return s;
    }

    /// <summary>
    /// Writes the three-player settings (state must be On or Outdated: the settings sit at the
    /// same place in every build). Every value is checked first; nothing is written if any is
    /// out of range.
    /// </summary>
    public void SetThreePlayerSettings(ThreePlayerSettings s)
    {
        RequireOn();
        ValidateThreePlayerSettings(s);

        var b = ThreePlayerPatch.Bal3Offset;
        WriteFloat(b + 0x08, s.MonsterHp);
        WriteFloat(b + 0x0C, s.MonsterDamage);
        WriteFloat(b + 0x10, s.XpValue);
        WriteFloat(b + 0x14, s.BossHp);
        WriteFloat(b + 0x18, s.GoldPerDrop);
        WriteFloat(b + 0x1C, s.ItemChance);
        WriteFloat(b + 0x20, s.GoldChance);
        WriteInt(b + 0x24, s.OrbDivisor);

        for (var p = 0; p < 3; p++)
        {
            var c = s.Markers[p];
            var w = MarkerAlpha | (uint)c.R | ((uint)c.G << 8) | ((uint)c.B << 16);
            BitConverter.GetBytes(w).CopyTo(_data, ThreePlayerPatch.MarkerOffset + p * 4);
        }

        WriteFloat(ThreePlayerPatch.SmallMapPosition, s.SmallMapX);
        WriteFloat(ThreePlayerPatch.SmallMapPosition + 4, s.SmallMapY);
        WriteFloat(ThreePlayerPatch.SmallMapSize, s.SmallMapWidth);
        WriteFloat(ThreePlayerPatch.SmallMapSize + 4, s.SmallMapHeight);
    }

    /// <summary>Throws <see cref="ArgumentException"/> naming the first bad value.</summary>
    public static void ValidateThreePlayerSettings(ThreePlayerSettings s)
    {
        void Factor(string name, float v)
        {
            if (float.IsNaN(v) || v < MinThreePlayerFactor || v > MaxThreePlayerFactor)
                throw new ArgumentException(
                    $"Three-player {name} must be between {Inv(MinThreePlayerFactor)} and {Inv(MaxThreePlayerFactor)}.");
        }

        Factor("monster HP", s.MonsterHp);
        Factor("monster damage", s.MonsterDamage);
        Factor("XP value", s.XpValue);
        Factor("boss HP", s.BossHp);
        Factor("gold per drop", s.GoldPerDrop);
        Factor("item drop chance", s.ItemChance);
        Factor("gold drop chance", s.GoldChance);
        if (s.OrbDivisor < MinOrbDivisor || s.OrbDivisor > MaxOrbDivisor)
            throw new ArgumentException(
                $"The Orb of Undeath divisor must be a whole number from {MinOrbDivisor} to {MaxOrbDivisor}.");

        if (s.Markers is null || s.Markers.Length != 3)
            throw new ArgumentException("Three marker colours are needed.");
        for (var p = 0; p < 3; p++)
        {
            var c = s.Markers[p];
            if (c.R is < 0 or > 255 || c.G is < 0 or > 255 || c.B is < 0 or > 255)
                throw new ArgumentException($"Player {p + 1} marker colour channels must be between 0 and 255.");
        }

        void Range(string name, float v, float lo, float hi)
        {
            if (float.IsNaN(v) || v < lo || v > hi)
                throw new ArgumentException($"Small-map {name} must be between {Inv(lo)} and {Inv(hi)}.");
        }

        Range("x", s.SmallMapX, -MaxSmallMapOffset, MaxSmallMapOffset);
        Range("y", s.SmallMapY, -MaxSmallMapOffset, MaxSmallMapOffset);
        Range("width", s.SmallMapWidth, MinSmallMapSize, MaxSmallMapSize);
        Range("height", s.SmallMapHeight, MinSmallMapSize, MaxSmallMapSize);
    }

    private void RequireOn()
    {
        if (GetThreePlayerState(out var detail) is not (ThreePlayerState.On or ThreePlayerState.Outdated))
            throw new InvalidOperationException("Three-player settings are not available: " + detail);
    }

    private void WriteFloat(int off, float value) => BitConverter.GetBytes(value).CopyTo(_data, off);
}
